        public static readonly ArtifactEncounterDef[] All =
        [
            new("1001", "Alvarus's Leggings", "Mesothalassa", "The mermaid Casyndra rotates through the three triton factions and sends you after a different thief for each: Thieving Octopus, the shark Razorfin, or Minkhat. You bring back an amulet, get a key, and the key opens a chest that only sometimes holds the leggings.", 12, [], null, "Casyndra's chest is locked. She says the thief who holds her amulet will come for the chest if it is disturbed.", [new("Something stirs in the rocks around the chest.", [new("Minkhat minion", 33801, 54, 62, 2, false)], 0, false), new("The thief comes for the chest.", [new("Thieving Octopus", 33738, 25, 65, 1, true)], 0, false)], "touch", true, null),
            new("1002", "Arms of the Winds", "Oceanus Notos", "A huge Raging Tornado circles the north end of the harpy isle, hitting for several hundred and pulsing a very large area blast. Dust devils come in from the north shore and heal it unless they are killed. It resists magic and pets.", 25, ["aoe_nuke", "summon_adds"], null, null, [], "touch", false, null),
            new("1003", "Aten's Shield", "Oceanus Hesperos", "Treasure Island off south-west Hesperos is covered in chests. A click makes a chest vanish with monsters, come up empty, or leave a glint that may be the shield. Clicking a spent chest brings very purple statues. Marble enforcers and magic-proof sentinels are the danger.", 12, [], null, "You crack the chest open. Something glints inside, and something else moves.", [new("The chest vanishes and its guardians stand in its place.", [new("marble enforcer", 994, 60, 48, 4, false)], 0, false), new("Sentinels step out of the stone. One of them holds something bright.", [new("sentinel", 998, 60, 55, 2, true)], 0, false)], "touch", false, null),
            new("1004", "A Flask", "Typhon's Reach", "A flask stands on a pedestal in the taur fortress at the east end of Typhon's Reach, and two taur Anax guard it. Lifting it sends every taur after the carrier, who must run with speed and shielding. Later patches reduced the numbers.", 12, ["aoe_nuke"], null, "The flask is warm and smells of old wine. Every taur in the fortress will know the moment you lift it.", [new("Taur pour in from the walls.", [new("taur phulax", 1191, 60, 65, 4, false), new("taur magos", 1191, 60, 65, 2, false)], 0, false), new("An Anax comes for the flask.", [new("taur Anax", 1190, 75, 75, 1, true)], 0, false)], "touch", false, null),
            new("1005", "Band of Stars", "Stygian Delta", "The snake Chisisi appears at one of two tombs after the small tomb snakes have been left alive for a few hours. She is easy enough to solo but drops the ring only sometimes.", 1, [], null, null, [], "touch", false, null),
            new("1006", "Bane of Battler", "Ashen Isles", "Battler stands on an island at Ashen 10k,20k. He starts at level 75 and grows each time he kills a player, up to about 83, stealing the abilities of the dead every three minutes. He is immune to magic and resets only on death or restart.", 12, [], null, null, [], "touch", false, null),
            new("1007", "Belt of the Moon", "Oceanus Boreal", "The pedestal on the dark Sunmoon island sits behind a deadly fire barrier and a ring of hesperis archers. You kill every protector of the dark on the island, the last kill gives a key, and the key holder dashes in and takes the belt.", 12, ["dd_nuke"], null, "The belt rests behind a shimmering barrier. Its protectors must fall before the barrier will open.", [new("The protectors of the dark rise to defend the pedestal.", [new("protector of dark", 907, 57, 50, 6, false)], 0, false), new("The hesperis close ranks around the pedestal.", [new("hesperis", 984, 62, 55, 3, false), new("Hesperis Warden", 984, 67, 61, 1, true)], 0, false)], "touch", false, null),
            new("1008", "Belt of the Sun", "Oceanus Boreal", "The same encounter as the Moon belt on the light island: kill every protector of the light, the last kill gives a key, and the key holder gets past the hesperis to the pedestal. Anyone else who goes near the barrier dies.", 12, ["dd_nuke"], null, "The belt rests behind a blazing barrier. Its protectors must fall before the barrier will open.", [new("The protectors of the light rise to defend the pedestal.", [new("protector of light", 912, 57, 50, 6, false)], 0, false), new("The hesperis close ranks around the pedestal.", [new("hesperis", 984, 62, 55, 3, false), new("Hesperis Warden", 984, 67, 61, 1, true)], 0, false)], "touch", false, null),
            new("1009", "Bracelet of Zo'arkat", "Mesothalassa", "The Triton Announcer runs the Coral Games in an arena past the bone arches. Nine waves of six champions rise in level, then one named champion falls and drops the bracer and three chest keys. Saying 'ready' sends the next wave early.", 50, [], null, "The Triton Announcer offers you the Silver Horn. Sound it and the Coral Games begin.", [new("Tier 1 of the Coral Games steps into the arena.", [new("coral games fighter", 33748, 52, 48, 6, false)], 0, false), new("Tier 2 of the Coral Games steps into the arena.", [new("coral games fighter", 33745, 52, 50, 6, false)], 0, false), new("Tier 3 of the Coral Games steps into the arena.", [new("coral games fighter", 33748, 52, 52, 6, false)], 0, false), new("Tier 4 of the Coral Games steps into the arena.", [new("coral games fighter", 33745, 52, 54, 6, false)], 0, false), new("Tier 5 of the Coral Games steps into the arena.", [new("coral games fighter", 33748, 52, 56, 6, false)], 0, false), new("Tier 6 of the Coral Games steps into the arena.", [new("coral games fighter", 33745, 52, 58, 6, false)], 0, false), new("Tier 7 of the Coral Games steps into the arena.", [new("coral games fighter", 33748, 52, 60, 6, false)], 0, false), new("Tier 8 of the Coral Games steps into the arena.", [new("coral games fighter", 33745, 52, 62, 6, false)], 0, false), new("Tier 9 of the Coral Games steps into the arena.", [new("coral games fighter", 33748, 52, 64, 6, false)], 0, false), new("The last champion of the Coral Games enters and breaks the horn.", [new("Coral Games Champion", 33747, 75, 68, 1, true)], 0, false)], "touch", true, null),
            new("1010", "Braggart's Bow", "Green Glades", "The stone archer Karise is frozen inside a ring of ten control links and guardians. The links must be destroyed before she can be hurt, then she is brought down. The older version allowed arrows only, and she dodges arrows after a patch. One group can do it slowly.", 25, [], null, "Karise stands in a ring of bound light. A thing made by cheating magic will not answer to magic.", [new("The control links flare to life around Karise.", [new("Karise", 987, 75, 65, 1, true), new("Control Link", 966, 50, 65, 10, false)], 0, true)], "touch", false, null),
            new("1011", "Bruiser", "Ashen Isles", "A taur forge citadel on the northern Ashen and Typhon border holds rooms of smithing hammers. Each hammer picked up mezzes those nearby and calls a wave of 10 to 15 minotaurs, with a foreman among the later ones. Waves get harder, and Bruiser is a random drop among the hammers.", 25, ["mez", "summon_adds"], null, "One of many smithing hammers lies here. Could this one be the legendary Bruiser? The forge falls quiet as you reach for it.", [new("A wave of smiths comes for the thief.", [new("taur craftsman", 1191, 60, 54, 8, false)], 0, false), new("Taur rush the forge floor.", [new("taur arieos", 1191, 60, 54, 10, false)], 0, false), new("Heavier taur join the fight.", [new("taur purphoros", 1190, 60, 57, 10, false)], 0, false), new("The taur guard arrives.", [new("taur koloios", 1191, 60, 62, 12, false)], 0, false), new("The Taur Foreman directs the last wave himself.", [new("taur guardian", 1190, 50, 61, 6, false), new("Taur Foreman", 1190, 75, 75, 1, true)], 0, false)], "touch", false, null),
            new("1012", "Ceremonial Bracer", "Mesothalassa", "Each triton faction has a heavy melee champion with a chance to drop the bracers: Skyros Dreadnought, Melos Wave Master or Tidal Lord, and Naxos Tidal Lord. They hit very hard and add a nuke or debuff proc.", 12, ["dd_nuke"], null, null, [], "touch", true, null),
            new("1013", "Cloudsong", "Green Glades", "Eramai the centaur asks for a music box. Destin in Aerus builds it from marble and bronze taken from Aerus statues at the corners of Green Glades. You hand the box to Eramai and kill him; he pulses and the cloak is roughly a one in ten drop, with very good other loot.", 12, ["aoe_nuke"], "Offline_Artifact_Key_Hand_Crafted_Music_Box", "Eramai will not fight for nothing. He wants to hear the box Destin made.", [new("The box plays, Eramai listens, and then he lowers his spear at you.", [new("Eramai", 1213, 70, 60, 1, true)], 0, false)], "touch", false, null),
            new("1014", "Crocodile Tear Ring", "Oceanus Boreal", "The named crocodile Cynere swims around the three crocodile islands with orange amaloi escorts. Killing her gives credit and sometimes the ring; she respawns in about 30 minutes.", 12, [], null, null, [], "touch", false, null),
            new("1015", "The Crocodile's Tooth", "Stygian Delta", "Itet patrols the river near Stygia 32k-50k,38k. He fights in melee and calls crocodiles, then at about 50% turns into a djinn form, charges a damage shield and pulses heavy blasts when his dagger hits the ground. Fighting underwater cut both the adds and the blasts.", 12, ["summon_adds", "aoe_nuke"], null, null, [], "touch", false, null),
            new("1016", "Crown of Zahur", "Oceanus Boreal", "Zahur floats by a magic rock with three minions: Boekide, Gohron and Danthena. Killed minions release energies that race to the rock and strengthen him unless destroyed first. He teleports around and returns to the rock to call the minions back.", 25, ["summon_adds", "dd_nuke"], null, null, [new("Zahur turns from the rock, and his three stand between you and him.", [new("Zahur", 33802, 50, 65, 1, true), new("Boekide", 33800, 50, 62, 1, false), new("Gohron", 33801, 50, 62, 1, false), new("Danthena", 33801, 50, 62, 1, false)], 0, true)], "near", true, null),
            new("1017", "Cyclops' Eye Shield", "Arbor Glen", "Kertom stands at the top of a ramp on a floating island with a dozen statues that stay asleep if the cyclops slaves at the bottom are cleared first. If Kertom is down, Kleps or Klops on a hill to the south can give the shield instead.", 12, [], null, null, [], "touch", false, null),
            new("1018", "Dream Sphere", "Stygian Delta", "Every four hours a tent camp at Stygia 42k,51k burns while a ghostly mau is attacked. One of three random waves comes: red dao, a rush of setians, or a swarm of scorpions. If the ghost survives he turns solid and gives the sphere to the group leader.", 12, ["dd_nuke"], null, "A pale mau flickers among the burning tents. Something is coming for him, and he begs you to stand with him.", [new("The ghost runs for the far tents with setians and scorpions at his heels.", [new("dream-bound setian", 1036, 50, 48, 5, false), new("dream-bound scorpion", 1263, 51, 50, 4, false)], 0, false, new("Ghostly Mau", 1041, 50, 50, 339412, 444516, 8050)), new("The Dao drift down above the tents.", [new("Dream-bound Dao", 1196, 50, 58, 4, false), new("Dream-bound Dao", 1196, 55, 60, 1, true)], 0, false)], "touch", false, null),
            new("1019", "Eerie Darkness Stone", "Oceanus Boreal", "Rougart, also written Bougart, is a large crocodile in a cave on a Boreal island with about ten yellow crocodile adds. A field in the cave absorbs magic, so this is a melee fight, and he never leaves the cave.", 12, [], null, null, [], "touch", false, null),
            new("1020", "Egg of Youth", "Oceanus Notos", "The giant harpy Sililia guards a nest on a hilltop reached through a path of harpies. Something protects her: ten columns around the lair must be broken before she can fall. The nest comes down, a player uses the egg and she dies with it.", 25, [], null, null, [new("The columns around the lair begin to glow. Something is protecting Sililia.", [new("Sililia", 992, 150, 65, 1, true), new("stone column", 997, 100, 60, 10, false)], 0, true)], "near", false, null),
            new("1021", "Eirene's Hauberk", "Mesothalassa", "Five idols of Sobek from the triton high priests buy half a key from Khonorn. Linos appears at one of three triton camps, takes the half key, promises a reward, turns on you, and his half opens a chest. Six level 50s can do it.", 12, [], "Offline_Artifact_Key_Khonorn_Half_Key", "The chest is crusted shut. Khonorn's half key is warm in your hand, and something answers it from the camp.", [new("Linos swims out to claim the key, grinning.", [new("Linos", 33747, 60, 75, 1, true)], 0, false)], "touch", true, null),
            new("1022", "Enyalio's Boots", "Arbor Glen", "Two sphinx guardians wait in a marble room on a floating island in south Arbor Glen. Farm a Small Crystalline Phial, kill the night-only jinni Behrooz, and return to the sphinxes, who wake together and need two groups. Wiping means a new phial and Behrooz again.", 25, ["disease"], "Offline_Artifact_Key_Small_Crystalline_Phial", "The chest will not open. The sphinxes say a jinni's essence must be brought here in the vessel they spoke of.", [new("A shade of Behrooz is drawn to the phial.", [new("Shade of Behrooz", 1198, 87, 64, 1, false)], 0, false), new("The guardians wake together.", [new("Enyalio's First Guardian", 1175, 100, 65, 1, true), new("Enyalio's Second Guardian", 1176, 100, 65, 1, true)], 0, false)], "touch", false, null),
            new("1023", "Eriny's Charm", "Typhon's Reach", "Six Siam-he lords (Setau, Taharga, Ausar, Kakhet, Nebkare, Sahathor) each leave a charm when killed. All six charms must be floated to a spot on the east shore within a time limit, then Samut ports over from his island and hits for 800 to 1300 with heavy regeneration.", 25, ["dd_nuke"], null, "Six charms must float here before their power fades. The lords of the camps carry them.", [new("The charms of the six lords gather at the shore.", [new("Charm of Setau", 1046, 50, 60, 1, false), new("Charm of Taharga", 1046, 50, 60, 1, false), new("Charm of Ausar", 1046, 50, 60, 1, false), new("Charm of Kakhet", 1046, 50, 60, 1, false), new("Charm of Nebkare", 1046, 50, 60, 1, false), new("Charm of Sahathor", 1046, 50, 60, 1, false)], 0, false), new("Samut steps across the lava.", [new("Samut", 1047, 65, 80, 1, true)], 0, false)], "touch", false, null),
            new("1024", "Eternal Plant", "Oceanus Notos", "A green plant hides in the Notos kelp forest. Seekers dragged to it call harvesters, and once they finish it Sobekhotep arrives with about seven bodyguards and drops the plant. He heals, and that must be stopped.", 12, ["summon_adds"], null, "A green plant stands out among the brown kelp. Seekers are drifting toward it.", [new("Sobekite harvesters swarm the plant.", [new("sobekite harvester", 33800, 45, 50, 6, false)], 0, false), new("The plant is gone. Sobekhotep pushes through the kelp with his bodyguards.", [new("Sobekhotep's bodyguard", 33801, 54, 50, 7, false), new("Sobekhotep", 33802, 75, 52, 1, true)], 0, false)], "touch", true, null),
            new("1025", "Fool's Bow", "Oceanus Notos", "One argo octopus in a deep underwater pit carries the bow. When it is up, frenzied harpies circle above, and the carrier flees oddly from players. The practical way was to clear every argo in the pit.", 12, [], null, null, [], "touch", true, null),
            new("1026", "Foppish Sleeves", "Arbor Glen", "Bergopes the giant cyclops stands on a ship at Arbor Glen 55k,9k and out-heals any damage. Cut a gorgon's head with the Kerubis Scythe, carry it in the Kibisis bag across the zone and use it on him to stop the healing for about 15 minutes. He throws players for 99% damage.", 25, ["stun"], "Offline_Artifact_Key_Blood_Soaked_Kibisis", "Bergopes laughs at the deck. Whatever he fears, you will need to carry it here in a bag.", [new("You raise the Kibisis, and a gorgon comes for what is in it. Bergopes flinches from her stare.", [new("Bergopes", 1231, 100, 65, 1, true), new("Gorgon Head Bearer", 1182, 50, 65, 1, false)], 0, true)], "touch", false, null),
            new("1027", "Goddess Necklace", "Oceanus Hesperos", "Four sisters in the Coral Sanctuary want an old treasure back. Bring at least two past the sharks to the Cave of the Dark Devilfish and click the overgrown statue when they are ready. The Dark Devilfish drives them off and drops the necklace. It has been soloed.", 3, [], null, "Weed-choked stone fills the cave. Nevsa's voice comes through the water behind you: stay close, and keep the sharks from me.", [new("Nevsa swims for the statue, and the hammerheads turn toward her.", [new("hammerhead shark", 33740, 50, 50, 3, false)], 0, false, new("Nevsa", 33748, 50, 42, 315844, 579588, 1301)), new("The spell is done. A dark shape uncoils from under the statue.", [new("Dark Devilfish", 33738, 70, 53, 1, true)], 0, false)], "touch", true, null),
            new("1028", "The Golden Spear", "Stygian Delta", "Three djinn, Landrine, Hounthro and Jomnaer, guard a spear by a pool at Stygia 59k,26k. Each must be engaged or one takes the spear and leaves. Jomnaer pulses, Hounthro mezzes and stuns, and Landrine heals from a cloud. Killing all three drops the spear.", 12, ["aoe_nuke", "mez", "stun"], null, null, [], "touch", false, ["Landrine", "Hounthro", "Jomnaer"]),
            new("1029", "Guard of Valor", "Green Glades", "Danos is a centaur with a huge health pool who roams a centaur village with two named friends and hits for 350 to 900, pure melee. One good group kills him in about ten minutes.", 12, [], null, null, [], "touch", false, null),
            new("1030", "Golden Scarab Vest", "Stygian Delta", "Earn Mau faction, then hand Tey Magical Scarab Wings from scarabs at Atum 55k,45k to get worthless gloves. The gloves let you lift the cursed vest near the east tent of the Mau camp, and they crumble when you do.", 3, ["root", "stun"], "Magical_Scarab_Wing", "The vest is wrapped in Bence's curse. Bare hands cannot lift it; scarab wings might draw the curse away.", [new("The curse claws its way out of the vest.", [new("cursed scarab", 1205, 50, 52, 4, false)], 0, false), new("Bence's curse takes shape.", [new("Bence's Curse", 1206, 75, 62, 1, true)], 0, false)], "touch", false, null),
            new("1031", "Harpy Feather Cloak", "Oceanus Notos", "Aedargy harpies nest on stone spires near Notos 18k,27k. One drops the cloak with a broadcast and a ghost harpy may steal it to the next tower. It has been soloed.", 3, [], null, null, [], "touch", false, null),
            new("1032", "Healer's Embrace Cloak", "Stygian Delta", "The purple lion Mesedsubastet roams southern Stygia and Atum with about five crazed lions, and each player he kills spawns another lion. He fights his way past the portal defenders and the Mau priest Pedibastet. The cloak is an uncommon drop.", 12, ["summon_adds"], null, null, [], "touch", false, null),
            new("1033", "Jacina's Sash", "Arbor Glen", "Cyrek stands at the end of a canyon of about thirty cyclops that mostly cannot be crowd controlled. Groups kite the adds away or pull Cyrek out by siege or speed, then kill him easily. It needs two groups or more.", 25, [], null, null, [], "touch", false, null),
            new("1034", "Kalare's Necklace", "Oceanus Notos", "The Warrior of Stone stands at Palaimon Shrine and does not fight back. He drops the Stone Encased Necklace, and whoever lifts it turns to stone while every statue on the island wakes, roots and debuffs them. The bearer must reach the water alive.", 3, ["root"], null, null, [new("The Warrior of Stone stands among the ruins and does not raise his sword.", [new("Warrior of Stone", 993, 100, 46, 1, false)], 0, false), new("You feel your skin harden. The statues of the island turn toward you.", [new("pristine statue", 993, 75, 45, 4, true)], 0, false)], "near", false, null),
            new("1035", "Gem of Lost Memories", "Oceanus Hesperos", "Night Terror, a turbaned dao jinni, appears at night by the central pillar of his island in Oceanus Hesperos. Each death splits him into weaker copies, two and then four, and all of them stun. A level 50 can solo him; the wait is the hard part.", 3, ["stun"], null, null, [new("A turbaned jinni drifts out from behind the pillar. The harpies scatter.", [new("Night Terror", 1196, 50, 42, 1, false)], 0, false), new("Night Terror comes apart, and two lesser shapes stand where he fell.", [new("Night Terror", 1196, 46, 40, 2, false)], 0, false), new("The shapes split again, weaker each time.", [new("Night Terror", 1196, 42, 38, 4, true)], 0, false)], "night", false, null),
            new("1036", "Maddening Scalars", "Typhon's Reach", "The giant snake Ylyssen rises near the Siam-he portal in Typhon's Reach. Players believe she forms from hidden snakes that spawn on deaths in the zone, and killing devotees may help. She stays put, nukes at random and stuns; heat heals her, and a ghost hands over the gauntlets.", 12, ["dd_nuke", "stun"], null, null, [], "touch", false, null),
            new("1037", "Malice Axe", "Typhon's Reach", "A ring of gold and stone holds an axe on a pedestal, with the Chest of Disciples and the Chest of Weakening behind it. Touching the axe wakes the minotaur Malamis. Only filling both chests with 100 tokens each stops his disciples healing him and lets him fall; after that he is a plain fight.", 12, [], null, "Gold lies heaped around the pedestal. A token comes away in your hand, and something vast stirs.", [new("Malamis wakes. His chests must be broken open, or nothing will hurt him.", [new("Malamis", 1190, 85, 70, 1, true), new("Chest of Disciples", 2362, 70, 60, 1, false), new("Chest of Weakening", 2362, 70, 60, 1, false), new("disciple of Malamis", 1191, 60, 60, 2, false)], 0, true)], "touch", false, null),
            new("1038", "Nailah's Robes", "Land of Atum", "Sebak leaves the Fortress of Storms with six to eight orange guards and tours the setian camps before returning. He is hard to hit and immune to magic. The robe does not always drop.", 12, [], null, null, [], "touch", false, null),
            new("1039", "Night's Shroud Bracelet", "Oceanus Anatole", "Beat Ki'atra for the Ketos Harness and use it on the Nervous Ketos so it turns back into Uilani, then bring her to a shipwreck in Anatole. Her spell opens the hull, and inside Kythera calls four Returned. All five are purple and hit hard.", 25, ["dd_nuke", "summon_adds"], "Offline_Artifact_Key_Ketos_Harness", "A crack runs down the port hull. Uilani waits for the Ketos Harness before she will begin.", [new("Uilani swims along the hull, chanting, and things in the wreck try to stop her.", [new("Kythera's Returned", 33746, 52, 58, 2, false)], 0, false, new("Uilani", 33748, 52, 50, 419606, 557207, 4240)), new("The hull splits open. Kythera calls the Returned to her.", [new("Kythera's Returned", 33746, 52, 62, 4, false), new("Kythera", 33750, 50, 75, 1, true)], 0, false)], "touch", true, null),
            new("1040", "Belt of Oglidarsh", "Oceanus Hesperos", "One orange leopard shark near Hesperos 48k,42k is possessed. It attacks other leopard sharks, takes no damage at first, and if another shark kills it the power moves on. The carrier returns within ten minutes.", 3, [], null, null, [], "touch", true, null),
            new("1041", "Orion's Belt", "Oceanus Hesperos", "Peridas, cursed for killing the hunter Orion, waits on her island in Hesperos. She fights as a harpy, turns ghostly for a moment, returns as a crocodile, does it again and ends as a large iaculus that nukes and poisons. Each form starts at full health. A single 50 can do it.", 3, ["aoe_nuke", "dd_nuke"], null, null, [new("A harpy drops from the rocks, screaming a name: Orion.", [new("Peridas", 990, 50, 42, 1, false)], 0, false), new("Peridas fades to a ghost for a breath, and a crocodile hauls itself out of her shape.", [new("Peridas", 1259, 100, 44, 1, false)], 0, false), new("The ghost flickers once more, and the curse settles on its last shape.", [new("Peridas", 1233, 60, 46, 1, true)], 0, false)], "near", false, null),
            new("1042", "Phoebus Harp", "Mesothalassa", "Three tritons near Meso 30k,7k trade the harp: Zoea, Hallea and Kosma. The holder emits notes and calls adds that all assist on one target. Reports say Hallea gave credit and Zoea the item.", 12, ["mez", "summon_adds"], null, null, [], "touch", true, ["Hallea", "Zoea", "Kosma"]),
            new("1043", "Ring of Fire", "Typhon's Reach", "The djinn Soleh, outside the neutral taur town, challenges a full group. She ports you to an island where three rounds of 6 to 8 taur guardians await; the later ones heal themselves. Then she ports you to an altar and one player takes the ring.", 12, [], null, "Soleh looks you over. Bring seven friends, she says, and prove you can survive what she calls up.", [new("The first taur guardians appear.", [new("taur guardian", 1190, 50, 61, 6, false)], 0, false), new("A stronger group arrives, healing as it fights.", [new("taur guardian", 1190, 50, 62, 7, false)], 0, false), new("Soleh calls the last of them.", [new("taur guardian", 1190, 50, 63, 6, false), new("Soleh's Warden", 1190, 70, 68, 1, true)], 0, false)], "touch", false, null),
            new("1044", "Ring of Unyielding Will", "Oceanus Notos", "Dorawm, on the island split by the Hesperos and Mesothalassa line, asks you to kill Mordom on the sea floor just across the Notos line and bring his necklace. Mordom releases gray barracudas. Dorawm may refuse the necklace, and he is the harder of the two with an area stun. Killing either gives credit.", 3, ["summon_adds"], null, null, [], "touch", false, null),
            new("1045", "Scepter of the Meritorious", "Oceanus Boreal", "Ferenc, a crocodile man near Stygia Haven, offers a trial inside a ring. Eight waves of caster mobs rise from blue to orange, then he attacks himself. He parries heavily and respawns at once.", 12, ["dd_nuke", "mez"], null, "Ferenc asks if you have come to prove your merit. Step into the ring when you are ready; you have ten seconds.", [new("Blue casters appear in the ring.", [new("Ferenc's acolyte", 1032, 50, 46, 3, false)], 0, false), new("More acolytes step forward.", [new("Ferenc's acolyte", 1032, 50, 48, 4, false)], 0, false), new("The trial grows harder.", [new("Ferenc's adept", 1032, 52, 50, 4, false)], 0, false), new("The trial grows harder.", [new("Ferenc's adept", 1032, 52, 51, 4, false)], 0, false), new("Adepts crowd the ring.", [new("Ferenc's adept", 1032, 52, 52, 6, false)], 0, false), new("Adepts crowd the ring.", [new("Ferenc's adept", 1032, 52, 52, 5, false)], 0, false), new("Ferenc's best step in.", [new("Ferenc's master", 1032, 54, 54, 5, false)], 0, false), new("Three masters remain.", [new("Ferenc's master", 1032, 54, 55, 3, false)], 0, false), new("Ferenc nods, and steps into the ring himself.", [new("Ferenc", 1034, 50, 63, 1, true)], 0, false)], "touch", false, null),
            new("1046", "The Scorpion's Tail", "Stygian Delta", "The giant scorpion Terkari wanders rocky spots across Stygia with ten or more yellow scorpions. Cold attacks stop his poison blasts. Three players did it by kiting the adds. The ring is rare.", 12, ["aoe_nuke", "disease"], null, null, [], "touch", false, null),
            new("1047", "Shades of Mist", "Typhon's Reach", "A statue in northwest Typhon's Reach wears a long black cloak that powers three greater criosphinxes. They cannot be harmed until the statue is touched; take the cloak and they weaken and chase its wearer. When all are dead the cloak turns into the artifact outside the ring.", 12, [], null, "A long black cloak hangs from the statue's shoulders. The air around the sphinxes hums with its power.", [new("The cloak comes away and the sphinxes wake.", [new("weakened criosphinx", 1177, 100, 62, 2, false)], 0, false), new("The last sphinx charges the cloak's bearer.", [new("weakened criosphinx", 1177, 100, 64, 1, true)], 0, false)], "touch", false, null),
            new("1048", "Mariasha's Sharkskin Gloves", "Oceanus Hesperos", "A Heavy Strongbox lies on the sea floor in shark water. Lifting it puts the Weight of Atlantis on you, and the docile coral sharks rush the carrier. Kill them, or in the older version outrun them to the island to the west, and the box opens.", 3, ["snare"], null, "The strongbox is far heavier than it looks. The Weight of Atlantis drags at you as you lift it.", [new("Coral sharks catch the scent of the strongbox and come in a swarm.", [new("coral shark", 33739, 35, 48, 6, true)], 0, false)], "touch", true, null),
            new("1049", "Shield of Khaos", "Green Glades", "Chief Creon rules a large centaur camp with 30 or more adds and healers. He will not cross a line near 22k,40k. One well built group can do it with area damage and heal fields in about 35 minutes.", 12, ["summon_adds"], null, null, [], "touch", false, null),
            new("1050", "The Snakecharmer's Weapon", "Land of Atum", "The snake charmer Maedion walks the Necropolis ridge playing his flute while iaculus snakes appear around him. When he stumbles the snakes turn on him. You clear them, keep him alive to the far ruins and speak to him for the reward; attacking him ruins it.", 12, [], null, "Maedion lifts his flute and asks you to walk the ridge with him. The snakes will come as soon as he plays.", [new("Maedion plays and walks west. Then he stumbles, and the snakes turn on him.", [new("ridge iaculus", 1233, 40, 48, 10, false)], 0, false, new("Maedion", 1041, 50, 50, 236876, 409816, 9446)), new("At the ruins the last snakes rise around you.", [new("ridge iaculus", 1233, 40, 50, 4, true)], 0, false)], "touch", false, null),
            new("1051", "Snatcher", "Typhon's Reach", "Azar disguises himself as a purple Siam-he plebian roaming between camps, and turns back into a djinn at low health, warping around. Killing him in plebian form most often gave the bracer. Seven people did it.", 12, [], null, null, [], "touch", false, null),
            new("1052", "Staff of the God", "Mesothalassa", "A staff sits at the bottom of Mesothalassa in a shark nest. Lifting it brings every shark, so the carrier must get up to a boat and reach the lemon tree on an island in Hesperos, where the guarded tree cleanses it. Groups vary from three with escape skills to four groups.", 50, [], null, "The staff is fouled with old weed. As your hand closes on it, every shark in the deep turns.", [new("Jagger sharks tear out of the dark.", [new("jagger shark", 33739, 50, 52, 8, false)], 0, false), new("More sharks pile in on the staff bearer.", [new("jagger shark", 33739, 50, 54, 8, false)], 0, false), new("The nest's matriarch comes for the staff.", [new("Jagger Matriarch", 33739, 80, 72, 1, true)], 0, false)], "touch", true, null),
            new("1053", "Spear of Kings", "Oceanus Notos", "Olmagion fights in the Temple of Kings north of the Notos pier. He seals the doors, heals from a node, and at low health harpies pour in that die if dragged past a broken door. Rams help break a door. He is highly resistant to magic.", 12, ["dd_nuke"], null, null, [new("The doors of the temple grind shut, and a node of light feeds Olmagion.", [new("Olmagion", 994, 150, 65, 1, true), new("healing node", 966, 50, 60, 1, false)], 0, true), new("Harpies pour in through the roof.", [new("temple harpy", 992, 52, 55, 8, false)], 20, false), new("The temple shakes. What is left of Olmagion stands up.", [new("Olmagion's Shade", 994, 110, 60, 1, true)], 0, false)], "near", false, null),
            new("1055", "Tartaros' Gift", "Typhon's Reach", "High Priest Akil stands on a pad at the Siam-he portal and floods the fight with orange salamanders. A tank drags him off the pad while another player handles the salamanders with area damage. Seven people have done it.", 12, ["summon_adds"], null, null, [new("Salamanders pour from the lava as you near the priests.", [new("livid salamander", 1261, 75, 54, 6, false)], 0, false)], "near", false, null),
            new("1056", "Traitor's Dagger", "Oceanus Boreal", "Sadri the Traitor changes shape and moves between four sites around Boreal and Mesothalassa, fleeing just under sprint speed if you turn your back. He respawns quickly and drops the dagger about one kill in ten. It has been soloed.", 3, [], null, null, [], "touch", true, null),
            new("1057", "Traldor's Oracle", "Oceanus Boreal", "Earn Gaderian faction and their leader raids Traldor's treasure horde. Losing it turns the mercenaries against Traldor; they break his temple doors and die. Ten loyalists and Traldor remain, an easy orange fight once the loyalists fall.", 12, [], null, "The Gaderian raid has emptied Traldor's horde. Knock, and his unpaid mercenaries will do the rest.", [new("A Gaderian raider makes for the door while Traldoran mercenaries swarm him.", [new("traldoran mercenary", 978, 49, 46, 5, false)], 0, false, new("Gaderian Raider", 33748, 50, 45, 340680, 515752, 5303)), new("The doors give way. Traldor stands inside with what loyal men he has left.", [new("traldoran loyalist", 33746, 52, 52, 4, false), new("Traldor", 33747, 50, 55, 1, true)], 0, true)], "touch", true, null),
            new("1058", "The Winged Helm", "Oceanus Notos", "Hermes walks an island of statues, and no damage sticks until the frightening harpies have stripped his armour. A puller drags him to the harpies at the southwest ruins, the armour breaks off in stages and he then falls in seconds. It has been soloed.", 3, ["root"], null, null, [new("Hermes turns. Your blows ring off his armour while the harpies circle.", [new("Hermes", 998, 112, 50, 1, true), new("frightening harpy", 992, 52, 43, 3, false)], 0, true)], "near", false, null),
            new("1059", "Wing's Dive", "Arbor Glen", "The gorgon Keres waits in ruins by the Green Glades zone line. She polymorphs, stuns and lifetaps for up to 650, and bleed styles or deaths call snakes to help her. A full group needs 10 to 20 minutes.", 12, ["stun", "lifedrain", "summon_adds"], null, null, [], "touch", false, null),
            new("1063", "Ring of Dances", "Oceanus Notos", "On Desmona's island at Notos 25.8k,44.3k, digging in the trees eventually raises a harpy of the dance who drops the ring. It has nothing to do with Desmona herself. Two people can do it.", 12, [], null, "The ground here has been turned over. Something below answers your spade.", [new("A harpy bursts out of the ground.", [new("harpy of the dance", 992, 70, 60, 1, true)], 0, false)], "touch", false, null),
            new("1060", "Stone of Atlantis", "Stygian Delta", "After the Proof of Integrity quest gives a Golden Tuning Fork, you fight the Keeper of the Stone inside a setian fort. He turns invisible, calls 6 to 12 sauts, runs around, bolts and mezzes. Then the fork is used at a temple behind the fort.", 12, ["dd_nuke", "mez", "summon_adds"], "Offline_Artifact_Key_Golden_Tuning_Fork", "The stone hums, faintly. It wants a note you do not have.", [new("Setian sauts answer the Keeper's call.", [new("setian saut", 1036, 50, 56, 6, false)], 0, false), new("The Keeper of the Stone comes out of hiding.", [new("Keeper of the Stone", 1037, 50, 62, 1, true)], 0, false)], "touch", false, null),
            new("1062", "Flamedancer's Boots", "Arbor Glen", "A floating platform at about Arbor Glen 27k,7k holds a statue with a scarab door. An Aerus Truesight Potion from Deep Volcanus binds it to you, then three streams of centaurs attack with mages and healers added each time. Credit comes from picking up the boots.", 50, ["summon_adds"], "Offline_Artifact_Key_Aerus_Truesight_Potion", "The scarab door is shut to ordinary eyes. You will need a Truesight Potion to see it.", [new("Centaurs come up the ramps.", [new("flamedancer scout", 1214, 50, 58, 8, false)], 0, false), new("Mages join the rush.", [new("flamedancer scout", 1214, 50, 59, 6, false), new("flamedancer mage", 1213, 50, 60, 4, false)], 0, false), new("Sages and healers follow.", [new("flamedancer sage", 1213, 50, 62, 4, false), new("Flamedancer", 1215, 65, 72, 1, true)], 0, false)], "touch", false, null),
            new("1061", "Atlantis Tablet", "Mesothalassa", "A library has four doors, each with two purple triton guards, and five chests on the floor. Wrong chests hurt and call a purple triton; the right one calls the Guardian. She lies about her weakness, heals on some damage and splits on other damage.", 12, ["summon_adds"], null, "Five chests lie on the library floor. Only one holds what you came for.", [new("A triton zenes pops from the wrong chest.", [new("triton zenes", 33745, 50, 63, 1, false)], 0, false), new("The Guardian rises from the right chest, naming a weakness you should not trust.", [new("Guardian of the Tablet", 33749, 60, 70, 1, true), new("library guard", 33745, 50, 60, 2, false)], 0, true)], "touch", true, null),
        ];
    }
}
